class DashboardRange{const DashboardRange(this.from,this.to,this.label);final DateTime from,to;final String label;static DashboardRange fromPeriod(DashboardPeriod p,{DateTimeRange? custom}){final n=DateTime.now(),d=DateTime(n.year,n.month,n.day);switch(p){case DashboardPeriod.today:return DashboardRange(d,d.add(const Duration(days:1)),'اليوم');case DashboardPeriod.week:final s=d.subtract(Duration(days:d.weekday-1));return DashboardRange(s,d.add(const Duration(days:1)),'الأسبوع');case DashboardPeriod.custom:if(custom!=null)return DashboardRange(DateTime(custom.start.year,custom.start.month,custom.start.day),DateTime(custom.end.year,custom.end.month,custom.end.day).add(const Duration(days:1)),'فترة مخصصة');return DashboardRange(DateTime(n.year,n.month,1),DateTime(n.year,n.month+1,1),'الشهر');case DashboardPeriod.month:return DashboardRange(DateTime(n.year,n.month,1),DateTime(n.year,n.month+1,1),'الشهر');}}}
