class SalesTrendChart extends StatelessWidget{const SalesTrendChart({super.key,required this.sales,required this.from,required this.to,this.sellerId});final List<DashboardSalePoint> sales;final DateTime from,to;final String? sellerId;@override Widget build(BuildContext c){final rows=sellerId==null?sales:sales.where((s)=>s.sellerId==sellerId).toList();if(rows.isEmpty)return const Center(child:Text('لا توجد مبيعات في الفترة',style:TextStyle(color:Colors.black45)));final days=math.max(1,to.difference(from).inDays),b=<int,double>{};for(final s in rows){final i=s.createdAt.difference(from).inDays.clamp(0,days-1);b.update(i,(v)=>v+s.total,ifAbsent:()=>s.total);}final spots=List.generate(days,(i)=>FlSpot(i.toDouble(),b[i]??0));return LineChart(LineChartData(minX:0,maxX:(days-1).toDouble(),minY:0,gridData:const FlGridData(show:false),borderData:FlBorderData(show:false),titlesData:const FlTitlesData(show:false),lineBarsData:[LineChartBarData(spots:spots,isCurved:days>3,barWidth:3,color:farshaBurgundy,dotData:const FlDotData(show:false),belowBarData:BarAreaData(show:true,color:farshaBurgundy.withValues(alpha:.1)))]));}}
