Future<DashboardDataBundle> loadDashboardBundle({required FarshaRepository repository,required InstitutionMembership membership,required DashboardRange range,String? branchId})async{final v=await Future.wait<dynamic>([repository.loadAccessibleBranches(membership.institutionId),repository.loadDashboardSales(membership.institutionId,range.from,range.to,branchId:branchId),repository.loadDashboardPayments(membership.institutionId,range.from,range.to,branchId:branchId),repository.loadDashboardExpenses(membership.institutionId,range.from,range.to,branchId:branchId),repository.loadBranchReport(membership.institutionId,range.from,range.to),repository.loadInventory(membership.institutionId),membership.role==InstitutionRole.owner?repository.hasActiveAccountant(membership.institutionId):Future.value(true),repository.loadDashboardSales(membership.institutionId,range.from.subtract(range.to.difference(range.from)),range.from,branchId:branchId)]);return DashboardDataBundle(branches:v[0] as List<BranchRecord>,sales:v[1] as List<DashboardSalePoint>,payments:v[2] as Map<String,double>,expenses:v[3] as List<ExpenseRecord>,branchReport:branchId==null?(v[4] as List<BranchReportRecord>):(v[4] as List<BranchReportRecord>).where((x)=>x.branchId==branchId).toList(),inventory:v[5] as List<InventoryRecord>,hasAccountant:v[6] as bool,previousSales:v[7] as List<DashboardSalePoint>);}
